dir:

































  &DefaultButton;




function dir$dmkhuvuc(p){
  this.constructor(p);
}
dir$dmkhuvuc.prototype = new DirEvent();
dir$dmkhuvuc.prototype.afterInit = function(){
  var p = this._dir;
}
dir$dmkhuvuc.prototype.afterInit = function(renderType){
  var p = this._dir,g = p.grid()

  dir$dmkhuvucDisabledMasterField(p, g);

}

function dir$dmkhuvucDisabledMasterField(p, g){

  if(p.valForm('ma_kv').trim() != '')
  {
    p.setDisabled('ma_kv', true);
  }
  else
  {
    p.setDisabled('ma_kv', false);
  }
}






	.control-label.ma_kv, .control-label.ten_kv
	{	
		//font-weight:bold;	
		color: #499b98;;
	}








declare @codeExistsNewMsg nvarchar(256), @codeExistsEditMsg nvarchar(256)
select @codeExistsNewMsg = case when '@@lan' = 'v' then N'Mã khu vực đã tồn tại' else N'Area code is exists' end
select @codeExistsEditMsg = case when '@@lan' = 'v' then N'Mã khu vực đã tồn tại' else N'Area code is exists' end
